944 |     /// @notice The ```liquidateClean``` function allows a third party to repay a borrower's debt if they have become insolvent
945 |     /// @dev Caller must invoke ```ERC20.approve``` on the Asset Token contract prior to calling ```Liquidate()```
946 |     /// @param _sharesToLiquidate The number of Borrow Shares repaid by the liquidator
947 |     /// @param _deadline The timestamp after which tx will revert
948 |     /// @param _borrower The account for which the repayment is credited and from whom collateral will be taken
949 |     /// @return _collateralForLiquidator The amount of Collateral Token transferred to the liquidator
950 |     function liquidateClean(
951 |         uint128 _sharesToLiquidate,
952 |         uint256 _deadline,
953 |         address _borrower
954 |     ) external whenNotPaused nonReentrant approvedLender(msg.sender) returns (uint256 _collateralForLiquidator) {
955 |         if (block.timestamp > _deadline) revert PastDeadline(block.timestamp, _deadline);
956 | 
957 |         _addInterest();
958 |         uint256 _exchangeRate = _updateExchangeRate();
959 | 
960 |         if (_isSolvent(_borrower, _exchangeRate)) {
961 |             revert BorrowerSolvent();
962 |         }
963 | 
964 |         // Read from state
965 |         VaultAccount memory _totalBorrow = totalBorrow;
966 |         uint256 _userCollateralBalance = userCollateralBalance[_borrower];
967 |         uint128 _borrowerShares = userBorrowShares[_borrower].toUint128();
968 | 
969 |         // Prevent stack-too-deep
970 |         int256 _leftoverCollateral;
971 |         {
972 |             // Checks & Calculations
973 |             // Determine the liquidation amount in collateral units (i.e. how much debt is liquidator going to repay)
974 |             uint256 _liquidationAmountInCollateralUnits = ((_totalBorrow.toAmount(_sharesToLiquidate, false) *
975 |                 _exchangeRate) / EXCHANGE_PRECISION);
976 | 
977 |             // We first optimistically calculate the amount of collateral to give the liquidator based on the higher clean liquidation fee
978 |             // This fee only applies if the liquidator does a full liquidation
979 |             uint256 _optimisticCollateralForLiquidator = (_liquidationAmountInCollateralUnits *
980 |                 (LIQ_PRECISION + cleanLiquidationFee)) / LIQ_PRECISION;
981 | 
982 |             // Because interest accrues every block, _liquidationAmountInCollateralUnits from a few lines up is an ever increasing value
983 |             // This means that leftoverCollateral can occasionally go negative by a few hundred wei (cleanLiqFee premium covers this for liquidator)
984 |             _leftoverCollateral = (_userCollateralBalance.toInt256() - _optimisticCollateralForLiquidator.toInt256());
